"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

const STATUSES = ["idle", "pending", "success", "failure"] as const;

/** Where a submit button is in its cycle. */
export type SubmitStatus = (typeof STATUSES)[number];

/** Props for a submit button. Pass `status` to control it, or let it follow the promise `onSubmit` returns. */
export type SubmitButtonProps = Omit<ComponentPropsWithoutRef<"button">, "children" | "onSubmit"> & {
  /** The resting label, such as "Save changes". */
  children: ReactNode;
  /**
   * Runs on press. Return a promise: the button shows the spinner until it
   * settles, then the success label, or the failure label when it rejects.
   * A press while it runs is ignored.
   */
  onSubmit: () => void | Promise<void>;
  status?: SubmitStatus;
  defaultStatus?: SubmitStatus;
  onStatusChange?: (status: SubmitStatus) => void;
  /** Shown beside the spinner. Defaults to the resting label, so the person still reads what is running. */
  pendingLabel?: ReactNode;
  successLabel?: string;
  /** Names the next step, because the button stays pressable after a failure. */
  failureLabel?: string;
  /** Read out when the action fails. The visible label alone would only say "Try again". */
  failureMessage?: string;
  /** How long the success label stays, in milliseconds. Zero keeps it. A failure stays until the next press. */
  resetAfter?: number;
};

const SWAP: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
// A fade is not motion, so reduced motion keeps it and drops the rise and the blur.
const FADE: Transition = { duration: 0.15 };

const GLYPH = { viewBox: "0 0 16 16", fill: "none", stroke: "currentColor", strokeWidth: 1.75, "aria-hidden": true } as const;

// The arc turns at a constant speed: it stands for time passing, so easing would make it pulse.
function SpinnerGlyph() {
  return (
    <svg {...GLYPH} className="size-4 shrink-0 motion-safe:animate-spin">
      <circle cx="8" cy="8" r="5.5" className="opacity-25" />
      <path d="M8 2.5a5.5 5.5 0 0 1 5.5 5.5" strokeLinecap="round" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg {...GLYPH} className="size-4 shrink-0">
      <path d="m3 8.5 3.25 3.25L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function RetryGlyph() {
  return (
    <svg {...GLYPH} className="size-4 shrink-0">
      <path d="M13 8a5 5 0 1 1-1.6-3.7M13 2.5v2.75h-2.75" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

/**
 * A button for an action that takes time. The spinner, the check and the
 * retry label all appear inside it, and it keeps the width of its longest
 * state, so nothing beside it moves.
 */
export function SubmitButton({
  children,
  onSubmit,
  status,
  defaultStatus = "idle",
  onStatusChange,
  pendingLabel,
  successLabel = "Saved",
  failureLabel = "Try again",
  failureMessage = "That did not work. Try again.",
  resetAfter = 2000,
  className,
  type = "button",
  onClick,
  ...buttonProps
}: SubmitButtonProps) {
  const [ownStatus, setOwnStatus] = useState<SubmitStatus>(defaultStatus);
  const current = status ?? ownStatus;
  const reduceMotion = useReducedMotion();
  const running = useRef(false);
  const mounted = useRef(true);
  const timer = useRef<number | null>(null);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      if (timer.current !== null) window.clearTimeout(timer.current);
    };
  }, []);

  const goTo = (next: SubmitStatus) => {
    if (!mounted.current) return;
    if (status === undefined) setOwnStatus(next);
    onStatusChange?.(next);
  };

  const submit = async () => {
    if (running.current || current === "pending") return;
    running.current = true;
    if (timer.current !== null) window.clearTimeout(timer.current);
    goTo("pending");
    try {
      await onSubmit();
      goTo("success");
      if (resetAfter > 0 && mounted.current) timer.current = window.setTimeout(() => goTo("idle"), resetAfter);
    } catch {
      goTo("failure");
    } finally {
      running.current = false;
    }
  };

  const faces = {
    idle: children,
    pending: (
      <>
        <SpinnerGlyph />
        {pendingLabel ?? children}
      </>
    ),
    success: (
      <>
        <CheckGlyph />
        {successLabel}
      </>
    ),
    failure: (
      <>
        <RetryGlyph />
        {failureLabel}
      </>
    ),
  } satisfies Record<SubmitStatus, ReactNode>;
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, filter: "blur(4px)" };
  const announcement = { idle: "", pending: "", success: successLabel, failure: failureMessage }[current];

  return (
    <>
      <button
        {...buttonProps}
        type={type}
        data-status={current}
        // Not `disabled` while it runs: a disabled button drops keyboard focus.
        aria-disabled={current === "pending" || buttonProps["aria-disabled"]}
        onClick={(event) => {
          onClick?.(event);
          if (!event.defaultPrevented) void submit();
        }}
        className={cn(
          "inline-flex min-h-11 cursor-pointer touch-manipulation items-center justify-center rounded-full bg-primary px-5 text-sm font-medium text-primary-foreground outline-none",
          "motion-safe:transition motion-safe:duration-150 active:scale-97",
          "aria-disabled:cursor-progress aria-disabled:active:scale-100",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-50 disabled:active:scale-100",
          className,
        )}
      >
        {/* Every state sits in one grid cell, so the cell is as wide as the widest and the button never resizes. */}
        <span className="grid">
          {STATUSES.map((key) => (
            <motion.span
              key={key}
              aria-hidden={key !== current}
              initial={false}
              animate={key === current ? { opacity: 1, y: 0, filter: "blur(0px)" } : hidden}
              transition={reduceMotion ? FADE : SWAP}
              className="col-start-1 row-start-1 flex items-center justify-center gap-2 whitespace-nowrap"
            >
              {faces[key]}
            </motion.span>
          ))}
        </span>
      </button>
      {/* Outside the button, so the result is not also read as part of its name. */}
      <span className="sr-only" role="status">
        {announcement}
      </span>
    </>
  );
}
